import {renderScanTips} from './scan-tips.js?v=37';
// Original Korean teaching synthesis, not verbatim guideline text or an official ISUOG sequence.
export const acquisitionSources={
 first:['ISUOG 2023 · 11–14주 검사','https://doi.org/10.1002/uog.26106'],
 mid:['ISUOG 2022 · 중기 검사','https://doi.org/10.1002/uog.24888'],
 late:['ISUOG 2024 · 후기 검사','https://doi.org/10.1002/uog.27538'],
 planes:['20+2 단면 · 이동 순서와 랜드마크','https://pmc.ncbi.nlm.nih.gov/articles/PMC12401504/'],
 cns:['ISUOG 2020 · CNS 선별검사','https://doi.org/10.1002/uog.22145'],
 heart:['ISUOG 2023 · 심장 선별검사','https://doi.org/10.1002/uog.26224'],
 echo:['ASE 2023 · 태아 심초음파','https://www.asecho.org/wp-content/uploads/2023/07/PIIS0894731723002067-1.pdf'],
 cervix:['ISUOG 2022 · 자궁경부 측정','https://doi.org/10.1002/uog.26020']
};
const P=(start,move,landmarks,fix,ages,refs=['planes'])=>({start,move,landmarks,fix,ages,refs});
const protocols={
 head:P('태아의 정중시상면에서 머리–몸통 방향을 확인한 뒤, 머리의 축상면(Axial plane)으로 전환합니다. 양측 두개골이 대칭이 되도록 회전과 좌우 기울임을 조절합니다.', '정중선이 중앙에 오도록 유지하면서 머리 안에서 위아래로 짧게 스윕하여 양측 시상(Thalami)이 보이는 높이를 찾습니다. 앞뒤 기울임을 줄여 비스듬히 잘린 타원형 머리를 교정합니다.', '대뇌낫(Falx), 양측 시상, 시상 앞쪽의 투명중격강(CSP)을 확인합니다. 소뇌가 나타나지 않는 높이에서 두개골 윤곽이 대칭이어야 합니다.', '소뇌가 보이면 단면이 너무 낮거나 뒤로 기울어졌는지 확인합니다. HC는 두개골 바깥 윤곽에 타원을 맞추고, BPD는 사용한 성장곡선의 캘리퍼 방식에 맞춥니다.', ['초기에는 두개골 골화, 정중선, 양측 시상·측뇌실을 기준으로 높이를 맞춥니다. CSP를 반드시 보이게 하려고 과도하게 기울이지 않습니다.','BPD/HC 측정면에서 시상과 CSP를 확인하고, 소뇌가 포함되지 않도록 합니다.','골화 음영과 골반 내 진입으로 정중선이 가려지면 옆쪽 음향창을 찾습니다. 이전과 같은 측정 방식으로 비교하고 영상 제한을 기록합니다.'],['cns']),
 ventricle:P('정중선이 중앙인 머리 축상면에서 시작합니다. 머리와 탐촉자의 상대 방향을 확인하고 측뇌실 뒤쪽을 확대합니다.','시상 단면에서 조금 더 머리 꼭대기 쪽으로 평행 이동·스윕하여 측뇌실 심방(Atrium)과 맥락총 사구(Glomus)를 찾습니다.','Falx, 전두각(Frontal horns), CSP와 원위부 측뇌실 심방을 확인합니다. 심방 내측 벽이 선명하고 뇌실 장축이 짧게 잘리지 않아야 합니다.','심방 폭은 사구 높이에서 뇌실 장축에 수직으로, 내벽–내벽(Inner-to-inner)에 놓습니다. 근위 반구 음영은 반대 음향창으로 보완하며 비스듬한 폭을 재지 않습니다.',['초기 측뇌실은 맥락총이 대부분을 채웁니다. 후기 심방 폭 측정 기준을 초기 영상에 그대로 적용하지 않습니다.','맥락총 사구 높이와 측뇌실 벽의 선명도를 우선 확인한 뒤 측정합니다.','골화 음영을 피하도록 접근 창을 바꾸고 이전 검사와 같은 심방 부위를 비교합니다. 잘 안 보이는 쪽을 정상으로 단정하지 않습니다.'],['cns']),
 earlybrain:P('태아 머리의 정중시상면을 확인한 뒤 축상면으로 바꿉니다. 두개골 전체와 양측 반구가 들어오도록 확대합니다.','머리 안을 위아래로 짧게 스윕하면서 밝은 맥락총(Choroid plexus)이 양측에서 가장 대칭적으로 보이는 높이를 찾습니다.','타원형 두개골, 중앙 대뇌낫(Falx), 양측 측뇌실을 채우는 나비 모양 맥락총을 확인합니다.','두 맥락총의 높이가 다르면 사선 단면을 의심해 회전을 되돌립니다. 1분기의 나비 모양 표지는 주로 맥락총이며 양측 시상과 혼동하지 않습니다.',['CSP와 후기 심방 폭 기준을 요구하지 않고 주수에 맞는 두 반구와 맥락총의 대칭을 평가합니다.','중기에는 TVP로 전환하여 측뇌실 심방과 CSP를 확인합니다.','후기에는 TVP의 심방과 뇌 발달 소견을 재평가합니다.'],['first','cns']),
 cerebellum:P('먼저 머리의 축상 경시상면(TTP)을 맞춥니다. 대뇌낫을 중앙에 놓고 양측 시상과 앞쪽 CSP를 확인합니다.','앞쪽 머리 영역을 기준으로 단면의 뒤쪽이 후두와로 내려가도록 작은 후방 틸트(Posterior angulation)를 가합니다. 정해진 각도를 맞추기보다 실시간 영상에서 소뇌가 나타나는 지점까지 조금씩 조절합니다.','양측 소뇌반구(Cerebellar hemispheres), 중앙 충부 영역(Vermis), 뒤쪽 대조(Cisterna magna), 후두골을 정렬합니다. 앞쪽 CSP·시상과 후두와가 함께 보이는 적절한 사선 횡단면을 찾습니다.','과도한 틸트로 CM이 커 보이거나 소뇌가 비대칭이면 기울임을 줄입니다. CM 측정 시 충부 뒤쪽과 후두골 내측 사이를 맞춥니다. 충부 전체 평가는 정중시상면 등 별도 단면이 필요합니다.',['초기 후두와는 소뇌·제4뇌실·중뇌수도관·뇌간을 주수에 맞게 구분합니다. 완성된 아령 모양이나 고에코성 충부, CSP를 필수 조건으로 요구하지 않습니다.','19–20주 전에는 발달 중인 충부로 인해 제4뇌실이 열린 듯 보일 수 있습니다. NF가 필요한 경우 후두골 외측–피부 경계를 별도로 확인하며 NT와 구분합니다.','골화 음영을 피해 후두와를 재관찰합니다. NF를 후기의 필수 선별 지표로 반복 요구하지 않고 소뇌·CM과 이전 소견을 비교합니다.'],['cns']),
 face:P('얼굴 정중시상면에서 이마·코·턱을 찾고 얼굴이 향하는 방향을 확인합니다.','코 앞쪽으로 탐촉자를 이동한 후 얼굴을 정면으로 자르는 관상면(Coronal plane)을 얻습니다. 코끝에서 입술 쪽으로 짧게 스윕합니다.','코끝(Nasal tip), 두 비공(Nostrils), 상순(Upper lip)의 좌우 연속성이 한 단면에서 보이도록 미세 회전합니다.','한쪽 입술이 사라지면 비스듬한 면인지 확인합니다. 손·제대가 가리면 접근 창이나 태위를 바꿔 재관찰하고, 상순만으로 구개 전체를 판정하지 않습니다.',['상순이 매우 작으므로 과도한 확대보다 해상도와 얼굴 방향을 먼저 맞춥니다. 구개 평가는 별도의 관상·축상 접근이 필요할 수 있습니다.','두 비공과 상순을 동시에 포함하는 관상면을 저장하고 얼굴 윤곽과 함께 확인합니다.','얼굴이 자궁벽에 밀착되면 다른 접근 창과 재관찰을 이용합니다. 표면 렌더링만으로 입술 단면을 대신하지 않습니다.']),
 orbit:P('얼굴의 정중시상면에서 코와 이마를 찾습니다.','양쪽 눈을 가로지르는 축상면으로 전환하고, 두 안와가 같은 높이에서 가장 크게 보이도록 상하 스윕·미세 틸트합니다.','양측 안와(Orbits), 안구(Globes), 앞쪽 수정체(Lenses)가 좌우 대칭으로 나타나도록 맞춥니다.','안와 하나만 보이거나 크기가 다르면 사선 절단 여부를 먼저 교정합니다. 골성 안와 테두리만 보이는 이마 높이에서 눈 부위로 내려옵니다.',['작은 수정체를 확인할 수 있는 확대와 적절한 초점을 사용합니다. 얼굴 정면·축상 방향을 구분합니다.','두 수정체가 함께 나타나는 면을 선택하고 양측 크기·간격을 비교합니다.','안면골 음영이나 얼굴 앞의 손을 피해 접근 창을 바꿉니다. 한쪽만 관찰되면 제한을 기록합니다.']),
 facialprofile:P('머리와 몸통의 시상 방향을 찾고 얼굴 옆모습을 화면에 놓습니다.','좌우로 조금씩 스윕하여 코끝·비골·입술·턱이 한 줄로 연결되는 정확한 정중면을 찾습니다.','이마(Forehead), 비골(Nasal bone), 상악(Maxilla), 하악(Mandible), 턱끝(Chin)의 관계를 확인합니다.','양쪽 안와가 겹쳐 보이거나 턱이 짧아지면 방시상면인지 확인합니다. 태아 목이 지나치게 굽거나 젖혀졌다면 중립 자세를 기다립니다.',['비골·구개와 뒤쪽 NT를 함께 확인할 수 있는 정중면을 찾되, NT 측정은 전용 확대·캘리퍼 기준을 적용합니다.','상악과 하악의 상대 위치를 확인하고 코·입술 윤곽을 연속적으로 저장합니다.','얼굴의 전방 공간이 줄어들면 옆쪽 접근을 시도합니다. 턱이 가려진 영상을 정상 프로파일로 저장하지 않습니다.']),
 heart:P('태위와 태아 좌우를 먼저 정하고 복부 횡단면에서 위(Stomach)와 대동맥의 위치를 확인합니다.','복부에서 머리 쪽으로 평행하게 스윕하여 흉부 횡단 사강면(4CV)에 도달합니다. 심첨과 심방이 함께 보이도록 미세 회전합니다.','두 심방·두 심실, 심장 십자부(Crux), 중격, 승모판(Mitral valve)·삼첨판(Tricuspid valve)을 확인합니다. 좌우 심실의 형태와 심장 축을 함께 봅니다.','심첨이 짧게 잘리면 장축을 다시 맞춥니다. 중격이 초음파 빔과 나란할 때 생기는 가성 결손은 다른 입사각으로 확인하고 여러 심장 주기를 cine로 저장합니다.',['심장이 작고 빠르게 움직이므로 좁은 영상 폭과 높은 프레임률을 확보합니다. 필요시 짧은 색 도플러로 두 방실 유입을 보완합니다.','사강면만으로 검사를 끝내지 않고 LVOT→RVOT→3VV→3VT를 연속적으로 확인합니다.','흉곽 음영을 피해 접근하고 경미한 우심 우세와 뚜렷한 불균형을 구분합니다. 과도한 확대나 색 번짐으로 중격·판막이 가려지지 않게 합니다.'],['heart']),
 lvot:P('심첨이 짧아지지 않은 사강면에서 좌심실(Left ventricle)을 확인합니다.','머리 쪽으로 조금 기울이며 태아 오른쪽 어깨 방향의 대동맥 유출을 따라 미세 회전하여 좌심실–대동맥 장축을 펼칩니다.','좌심실, 대동맥판(Aortic valve), 상행대동맥(Ascending aorta), 심실중격–대동맥 전벽의 연속성을 확인합니다.','대동맥을 중간에서만 잡았다면 좌심실 기시부까지 되돌아가 추적합니다. RVOT와 연속 스윕하여 두 유출로의 교차 관계를 확인합니다.',['한 정지 프레임보다 좌심실에서 나가는 혈관의 연속성을 짧은 cine로 확인합니다. 작은 대동맥판의 세부 소견은 가시성에 맞게 기록합니다.','중격과 대동맥 전벽의 연결, 대동맥판 운동과 혈관 기시를 함께 확인합니다.','늑골·척추 음영을 피해 다른 입사각을 사용합니다. 판막 협착 등 진행성 소견이 의심되면 표적 심초음파로 평가합니다.'],['heart','echo']),
 rvot:P('사강면과 LVOT를 확보한 뒤 앞쪽 우심실(Right ventricle)을 확인합니다.','LVOT에서 조금 더 머리 쪽으로 스윕하고 미세 회전하여 우심실에서 주폐동맥(Main pulmonary artery)으로 이어지는 경로를 펼칩니다.','폐동맥판(Pulmonary valve), 주폐동맥과 폐동맥 분지(Bifurcation), 대동맥과의 교차를 확인합니다.','분지가 보이지 않으면 혈관을 따라 조금씩 위아래로 스윕합니다. 3VV의 혈관 단면만으로 우심실 기시가 확인되었다고 판단하지 않습니다.',['주폐동맥의 우심실 연결을 먼저 찾고, 분지는 확대와 짧은 색 도플러로 보완합니다. 보이지 않는 작은 분지를 단정하지 않습니다.','기시부–판막–분지를 연속적으로 저장하고 LVOT와 교차하는지 확인합니다.','큰 심장으로 한 화면에 경로가 안 들어오면 확대를 줄여 연결을 먼저 확인한 뒤 판막을 재확대합니다.'],['heart','echo']),
 threev:P('RVOT에서 주폐동맥과 분지를 확인합니다.','조금 더 머리 쪽의 상부 종격동 횡단면으로 이동하여 세 혈관을 같은 높이에서 확인합니다.','태아 왼쪽·앞쪽의 폐동맥(PA), 중앙 대동맥(Ao), 오른쪽·뒤쪽 상대정맥(SVC)의 배열과 상대 크기를 확인합니다.','태아의 좌우를 화면 좌우와 혼동하지 않습니다. 두 궁의 V자 합류를 보여주는 더 높은 3VT와 구분하고, 필요한 높이로 다시 내려옵니다.',['초기에는 색 도플러가 혈관 식별을 도울 수 있습니다. 혈관 개수만 세지 말고 위치와 유출로 연결을 확인합니다.','PA–Ao–SVC의 배열과 크기 균형을 확인하고 위쪽으로 스윕하여 3VT와 연결합니다.','우심계·폐동맥이 상대적으로 커질 수 있으나 뚜렷한 불균형은 별도 평가합니다. 후기라는 이유로 비대칭을 모두 정상 처리하지 않습니다.'],['heart']),
 threevpa:P('표준 3VV 또는 RVOT에서 주폐동맥의 기시와 분지를 확인하여 측정 혈관을 식별합니다.','사용할 정상 참고치가 요구하는 측정 위치·단면으로 옮깁니다. 3VV의 PA 직경과 RVOT의 폐동맥판륜(Pulmonary annulus) 측정을 구분합니다.','측정 위치의 양쪽 혈관벽을 확대하고 직경선이 혈관 장축에 수직인지 확인합니다.','성장곡선·검사실 프로토콜의 심장 주기와 캘리퍼 방식을 먼저 확인합니다. 측정법이 정해지지 않았다면 임의 위치의 직경을 정상치와 비교하지 않습니다.',['아주 작은 혈관은 색 번짐과 픽셀 크기의 영향을 크게 받습니다. 1분기용 참고치와 해당 측정법이 있을 때만 계측을 해석합니다.','폐동맥 줄기와 판륜을 혼동하지 않고 참고치와 같은 위치·주기로 반복 측정합니다.','이전 검사와 같은 측정 위치·방법으로 비교하고 PA/Ao의 크기 관계도 함께 확인합니다.'],['echo','heart']),
 vessels:P('3VV에서 PA·Ao·SVC의 위치를 확인합니다.','머리 쪽으로 조금 더 스윕하면서 후방으로 이어지는 동맥관궁과 대동맥궁이 하행대동맥으로 합류하는 면을 찾습니다.','기관(Trachea)의 위치와 그 왼쪽을 지나는 두 궁의 V자 합류, 오른쪽 SVC를 확인합니다. 필요시 색 도플러로 두 경로를 추적합니다.','단순히 세 혈관만 보이고 기관·합류가 없으면 3VV에 머무른 것입니다. 색 번짐을 줄이고 회전·기울임을 미세 조절하여 기관을 따로 식별합니다.',['작은 기관과 두 궁은 가시성이 제한될 수 있습니다. 짧은 색 도플러와 회색조를 번갈아 확인하고 두 궁이 보였는지 명시합니다.','기관을 기준으로 두 궁의 좌우 관계와 합류, 전향성 혈류를 확인합니다.','후기 혈관 크기 차이와 음영을 고려하되 두 궁의 연속성을 끝까지 추적합니다. 크기 불균형·비정상 경로는 정밀 평가로 연결합니다.'],['heart','echo']),
 aoarch:P('LVOT에서 상행대동맥을 확인하고 태아 몸통의 시상 방향을 파악합니다.','대동맥의 주행을 따라 종단 방향으로 회전·스윕하여 상행부–궁–하행부를 길게 펼칩니다.','대동맥궁(Aortic arch)의 곡선과 머리·팔로 나가는 분지, 협부(Isthmus), 하행대동맥 연결을 확인합니다.','분지가 보이지 않으면 동맥관궁을 잡은 것은 아닌지 LVOT 기시로 되돌아가 확인합니다. 한 번의 큰 회전 대신 연결을 따라 조금씩 이동합니다.',['상세 심초음파에 해당하는 접근입니다. 작은 분지와 협부의 가시성을 기록하고 후기 재평가를 계획합니다.','목 혈관 분지를 통해 동맥관궁과 구별하고 협부를 짧게 잘라 보지 않도록 합니다.','협부와 궁의 크기·연속성을 이전 소견과 비교합니다. 태위로 궁이 가려지면 다른 음향창에서 추적합니다.'],['echo']),
 ductarch:P('RVOT에서 주폐동맥을 찾고 우심실 기시를 확인합니다.','주폐동맥–동맥관(Ductus arteriosus)–하행대동맥의 경로를 따라 방시상 종단면으로 회전합니다.','완만한 곡선의 동맥관궁(Ductal arch)과 하행대동맥 연결을 확인하고 대동맥궁의 목 혈관 분지가 없는 경로인지 확인합니다.','V자 3VT만으로 종단궁을 대신하지 않습니다. 혈관이 끊겨 보이면 단면을 좌우로 조금씩 스윕해 실제 연결인지 확인합니다.',['교육·표적 심초음파 항목으로 접근합니다. 작은 동맥관은 짧은 색 도플러로 연결을 보완합니다.','우심실에서 시작하는 경로와 하행대동맥 합류를 하나의 연속 스윕으로 저장합니다.','동맥관이 좁거나 혈류가 비정상으로 보이면 단면 오류를 교정한 뒤 표적 도플러 평가를 시행합니다. 색상만으로 협착 여부를 결정하지 않습니다.'],['echo']),
 bicaval:P('사강면에서 우심방(Right atrium)을 찾고 태아의 머리–꼬리 축을 확인합니다.','우심방을 통과하는 우측 방시상 종단면으로 전환하며 상대정맥과 하대정맥이 연결되는 높이를 스윕합니다.','위쪽 상대정맥(SVC), 아래쪽 하대정맥(IVC), 우심방 유입과 심방중격의 관계를 확인합니다.','대동맥을 정맥으로 오인하지 않도록 우심방까지 실제 연결을 추적합니다. 필요시 적절한 색 도플러 설정으로 정맥 유입을 보완합니다.',['작은 정맥의 연결이 불명확하면 관찰 제한을 명시합니다. 일반 선별검사와 상세 심초음파의 범위를 구분합니다.','두 대정맥을 우심방과 같은 종단면에 맞추고 각각의 연결을 저장합니다.','태아 몸통 굴곡이나 음영 때문에 두 정맥이 함께 안 보이면 개별 추적 영상도 남깁니다.'],['echo']),
 abdomen:P('태아 몸통의 시상면에서 척추 방향을 확인한 뒤 복부 횡단면으로 전환합니다.','위(Stomach)를 찾고 제대정맥이 문맥동(Portal sinus)으로 이어지는 높이까지 짧게 스윕합니다. 몸통 축에 수직이 되도록 틸트합니다.','둥근 복부, 왼쪽 위, 제대정맥·문맥동, 척추 횡단면을 확인합니다. 심장과 신장이 들어오는 높이는 피합니다.','복부가 길쭉하거나 한쪽 늑골만 길게 보이면 사선 단면을 교정합니다. AC 타원은 피부 바깥 경계를 따라 놓고 과한 압박을 줄입니다.',['복벽·위·장기 위치를 먼저 평가합니다. AC 계측은 해당 초기 주수에 맞는 적응증과 참고치를 사용합니다.','위와 문맥동을 포함하고 신장을 제외하는 표준 AC 단면으로 저장합니다.','피부 윤곽이 화면 밖으로 잘리지 않게 깊이를 조절합니다. 태동·호흡운동이 줄어든 때 동일 기준으로 재측정합니다.']),
 cord:P('복부 횡단면에서 앞쪽 복벽과 제대정맥을 찾습니다.','앞쪽 복벽을 따라 머리–꼬리 방향으로 스윕하여 제대가 복벽을 통과하는 부위를 축상면으로 맞춥니다.','복벽 연속성, 제대 삽입부(Abdominal cord insertion), 복부 안으로 이어지는 제대정맥(Umbilical vein)을 확인합니다.','태반 쪽 제대 부착부나 자유 제대 고리를 태아 복벽 삽입부로 혼동하지 않습니다. 필요시 시상면과 짧은 색 도플러로 실제 연결을 재확인합니다.',['초기 생리적 중장 탈출과 주수에 맞지 않는 지속 탈출을 구분해야 합니다. 주수·형태를 함께 확인하고 불확실하면 추적 평가합니다.','복벽을 가로지르는 삽입부를 확대하고 전방 복벽 결손 여부를 확인합니다.','복부가 커져 삽입부가 한쪽에 치우치면 탐촉자를 이동하여 정면으로 접근합니다. 제대 그림자로 복벽이 끊겨 보이는지 확인합니다.']),
 diaphragm:P('복부와 흉부의 경계를 찾고 몸통 시상면에서 간·위와 심장·폐의 위치를 확인합니다.','정중면에서 좌우 방시상면으로 스윕하여 각각의 횡격막을 길게 펼치고, 관상면으로 전환해 양쪽을 보완합니다.','흉강의 폐와 복강의 간·위 사이에 있는 곡선의 횡격막(Diaphragm) 연속성을 확인합니다.','한쪽 곡선만 보고 양쪽이 정상이라고 판단하지 않습니다. 늑골 음영·폐 아래 경계를 횡격막과 혼동하면 인접 면을 연속 스윕합니다.',['작은 횡격막 선의 직접 관찰이 제한될 수 있습니다. 위·간의 복부 위치와 흉부 장기 배치를 함께 확인합니다.','좌우 반횡격막을 각각 종단면으로 저장하고 위·심장 위치와 비교합니다.','후기에 처음 드러나는 소견이 있을 수 있어 재관찰합니다. 흉곽 음영을 피하고 한쪽이 가려진 경우 제한을 남깁니다.']),
 kidneys:P('AC 단면에서 시작하여 척추가 보이는 복부 횡단면을 유지합니다.','약간 꼬리 쪽으로 내려가 척추 양옆의 양측 신장을 찾고 신우(Renal pelvis)가 보이는 높이까지 미세 스윕합니다.','양측 신장(Kidneys), 신우, 척추와의 관계를 확인합니다. 두 신장을 모두 포함하되 사선으로 길게 잘리지 않도록 맞춥니다.','신우 전후경은 신장 횡단면에서 내측 경계 사이를 재고 비스듬한 대각선 계측을 피합니다. 근위 신장 음영은 반대쪽 창으로 보완합니다.',['초기 신장은 작고 상대적으로 밝습니다. 양측 존재는 관상면으로도 확인하며 후기 신우 기준을 그대로 적용하지 않습니다.','양측 신장과 신우를 분리 확인하고 필요한 경우 횡단 전후경을 측정합니다.','피질·수질 분화와 신우 변화를 이전 검사와 비교합니다. 주수에 맞는 요로확장 기준을 사용하고 방광·양수 평가를 함께 합니다.']),
 kidneysag:P('신장 횡단면에서 좌우 신장을 먼저 식별합니다.','한쪽 신장을 중심으로 몸통 장축에 맞춰 회전한 뒤 앞뒤로 조금씩 스윕하여 가장 긴 신장 축을 찾습니다.','상극·하극, 신장 피질과 수질, 중심 신우가 이어지는 종단면(Longitudinal kidney)을 확인합니다.','상극이나 하극이 잘리면 짧은 길이를 기록하지 말고 장축을 다시 맞춥니다. 반대쪽 신장을 같은 방법으로 따로 획득합니다.',['1분기에는 상세 종단 구조가 제한되므로 양측 존재·위치 확인을 우선합니다.','신장 장축과 몸통 축이 완전히 같다고 가정하지 말고 각 신장을 따로 정렬합니다.','확장된 신우와 수질 피라미드를 구분하며 양극을 모두 포함합니다. 신장 길이와 신우 전후경은 서로 다른 단면에서 평가합니다.']),
 kidneycor:P('몸통의 척추와 양측 신장 위치를 횡단면에서 먼저 확인합니다.','척추에 평행한 관상 방향으로 전환하고 앞뒤로 스윕하여 양쪽 신장이 동시에 보이는 면을 찾습니다.','척추 양쪽의 신장, 상극·하극의 위치, 양측 크기 균형을 확인합니다.','한쪽 신장만 보이면 회전이 남았는지 확인하고 각 신장을 따로 추적합니다. 관상면 신우 폭을 횡단 AP 직경과 혼용하지 않습니다.',['척추 옆의 밝은 신장 두 개를 찾는 데 유용합니다. 부신을 신장으로 오인하지 않도록 위치와 윤곽을 연속 추적합니다.','두 신장을 동시에 확인하되 횡단·종단면으로 내부 구조를 보완합니다.','태아 굴곡으로 양쪽 장축이 한 면에 안 들어오면 각각 저장하고 동시 관찰의 제한을 기록합니다.']),
 pelvis:P('복부 횡단면에서 척추와 제대 삽입부를 확인합니다.','꼬리 쪽 골반으로 스윕하여 중앙의 무에코 방광(Bladder)이 가장 잘 보이는 높이를 찾습니다.','방광의 벽과 내용물, 양옆 제대동맥(Umbilical arteries)의 주행을 확인합니다. 필요시 색 도플러를 짧게 사용합니다.','방광이 비어 안 보이면 시간차를 두고 재관찰합니다. 다른 낭성 구조와 혼동하지 않도록 골반 정중선과 동맥 관계를 확인합니다.',['방광의 존재·위치를 우선 확인합니다. 커 보이는 방광의 길이는 별도 정중시상면과 초기 기준으로 평가합니다.','충만·배출 양상을 관찰하고 양측 제대동맥과 연결을 확인합니다.','방광 크기·벽 두께와 양측 신장, 양수 상태를 함께 비교합니다. 한 번의 비어 있는 프레임으로 방광 부재를 판단하지 않습니다.']),
 spine:P('전체 태아를 보며 머리부터 천골까지 척추의 경로와 등 쪽 피부를 찾습니다.','먼저 시상면에서 길게 따라가고, 이어 관상면과 여러 높이의 횡단면으로 전환해 경추–흉추–요추–천추를 순서대로 스윕합니다.','척추 골화 중심(Ossification centers), 정렬, 뒤쪽 피부(Skin)의 연속성과 천골 끝을 확인합니다.','뼈만 이어 보이는 영상으로 피부 평가를 대신하지 않습니다. 한 구간이 음영에 가려지면 접근 방향을 바꾸고 놓친 높이를 따로 저장합니다.',['작은 척추 골화 중심과 등 피부를 함께 확인하며 머리 후두와 소견도 연계합니다.','척추 전체를 여러 방향으로 확인하고 특히 요천추와 그 위 피부를 빠뜨리지 않습니다.','골화·굴곡으로 전체가 한 화면에 안 들어오면 구간별로 겹치게 저장합니다. 기존 이상 부위를 집중 재관찰합니다.']),
 femur:P('골반을 찾고 고관절에서 이어지는 허벅지 뼈를 확인합니다.','고관절–무릎을 따라 스윕하며 탐촉자를 대퇴골 장축과 나란한 영상면으로 회전합니다. 골간이 가장 길게 보이는 면을 찾습니다.','대퇴골(Femur)의 골화된 골간 양 끝을 선명하게 포함합니다. 빔이 골간에 가능한 수직에 가깝게 들어오도록 조절합니다.','비스듬히 잘려 짧아 보이면 다시 정렬합니다. 골단과 끝의 삼각형 돌출 인공물은 길이에서 제외합니다.',['초기에는 허벅지·하퇴·발의 세 부분과 연결을 우선 확인하고 계측 적응증을 구분합니다.','골화된 골간의 끝–끝 길이를 재고 사용한 성장곡선에 맞춥니다.','후기에 보이는 원위 골단 골화 중심을 FL에 포함하지 않습니다. 양 끝을 잃지 않도록 깊이·확대를 조절합니다.']),
 tibia:P('무릎에서 하퇴로 이어지는 다리 방향을 찾습니다.','하퇴 장축에 맞춰 회전한 뒤 좌우로 조금씩 스윕하여 경골과 비골 두 뼈를 펼칩니다.','경골(Tibia), 비골(Fibula), 무릎과 발목의 연결 및 발의 방향을 확인합니다.','두 뼈가 겹치면 입사각을 바꾸고 각각 추적합니다. 대퇴골이나 다른 쪽 다리를 같은 하퇴 뼈로 혼동하지 않습니다.',['하퇴와 발의 연결·방향을 먼저 확인하고 매우 작은 두 뼈의 개별 관찰 여부를 기록합니다.','두 장골과 발목 위치를 한 장축 스윕에서 확인하고 반대쪽도 반복합니다.','다리가 접히거나 겹치면 고관절부터 해당 다리를 다시 추적하여 좌우를 구분합니다.']),
 foot:P('경골·비골의 끝에서 발목을 찾습니다.','발목을 지나 발의 장축으로 방향을 바꾸고 발바닥(Plantar surface)을 펼치는 면을 찾습니다.','뒤꿈치(Heel), 발바닥, 발가락(Toes)과 하퇴의 상대 방향을 확인합니다.','발이 늘 하퇴와 같은 면에 겹쳐 보이면 다른 방향과 태동 시에도 확인합니다. 일시적 자세만으로 고정된 변형을 판단하지 않습니다.',['작은 발의 존재와 하퇴 연결, 움직임을 확인합니다. 모든 발가락을 한 프레임에서 세는 것을 필수로 요구하지 않습니다.','양측 발바닥과 하퇴에 대한 정렬을 확인하고 필요시 다른 면으로 보완합니다.','발이 자궁벽·다른 다리에 밀착되면 태동 후 재관찰합니다. 눌린 자세와 지속되는 이상 정렬을 구분합니다.']),
 humerus:P('흉곽에서 어깨를 찾고 위팔이 이어지는 방향을 확인합니다.','어깨에서 팔꿈치까지 따라가며 상완골 장축에 맞춰 회전하고 가장 긴 골간 면을 찾습니다.','상완골(Humerus) 양 끝과 어깨·팔꿈치 연결을 확인합니다.','전완골과 혼동하지 않도록 어깨 기시를 다시 확인합니다. 길이 측정 시 골화된 골간만 포함하고 단축된 사선 면을 피합니다.',['상완·전완·손의 세 부분을 우선 확인하고 양측 상지를 추적합니다.','양측 상완골의 형태와 길이 균형, 팔꿈치 연결을 확인합니다.','팔이 흉곽에 붙어 있으면 어깨에서부터 연속 추적하며 늑골과 분리합니다.']),
 forearm:P('상완골을 따라 팔꿈치를 찾고 전완부 방향을 확인합니다.','팔꿈치–손목 장축으로 회전한 뒤 미세 스윕하여 요골과 척골을 각각 펼칩니다.','요골(Radius), 척골(Ulna), 손목과 손의 정렬을 확인합니다.','뼈가 겹치면 입사각을 바꿉니다. 손목 쪽만 보고 근위부를 빠뜨리지 말고 팔꿈치부터 끝까지 추적합니다.',['작은 두 뼈와 손의 존재·방향을 우선 봅니다. 손목의 세밀한 구조를 후기와 동일하게 요구하지 않습니다.','두 전완골을 구분하고 손과의 정렬을 양측에서 확인합니다.','손이 얼굴 앞에 있으면 전완부를 따라 손목까지 추적하여 다른 팔과 혼동하지 않습니다.']),
 hand:P('전완골을 따라 손목을 찾습니다.','손바닥 면과 손등 쪽을 짧게 스윕하고 손이 펴지는 순간을 기다려 손가락을 관찰합니다.','손바닥(Palm), 엄지(Thumb), 손가락(Fingers), 손목의 상대 위치와 움직임을 확인합니다.','주먹을 쥔 한 프레임에서 손가락 수나 고정 변형을 단정하지 않습니다. 다른 면과 시간차 영상으로 보완합니다.',['양쪽 손과 손목 정렬·움직임을 확인합니다. 손가락 개수의 완전한 확인은 작은 크기 때문에 제한될 수 있습니다.','펴진 손에서 손가락과 엄지 위치를 확인하고 지속적 쥠이 의심되면 재관찰합니다.','얼굴·제대에 가려진 손은 전완에서 다시 추적합니다. 지속 자세인지 태동 중 변화하는지 확인합니다.']),
 genitalia:P('태아의 골반과 양쪽 허벅지를 찾습니다.','회음부(Perineum)를 통과하는 면을 얻고 시상·횡단 방향으로 보완하여 다리 사이 구조를 확인합니다.','주수에 맞는 외부 생식기(External genitalia)와 주변 연조직을 확인합니다.','다리 사이 제대와 생식기를 혼동하지 않도록 연속 스윕합니다. 한 각도만으로 성별이나 정상 구조를 확정하지 않습니다.',['정중시상면에서 생식결절(Genital tubercle)과 몸통 축의 관계를 봅니다. 후기 음낭·음순 모양을 초기의 필수 소견으로 요구하지 않습니다.','적절한 회음부면에서 외부 구조를 확인하고 필요시 시상면을 보완합니다.','다리의 겹침과 제대에 의한 가림을 확인하고 충분히 분리된 면에서 관찰합니다.']),
 placenta:P('자궁 전체를 넓게 스윕하여 태반의 위치와 자궁경부 쪽 방향을 확인합니다.','태반 몸통에서 가장자리로 연속 이동하고 하연이 낮으면 내자궁구(Internal os)를 포함하는 자궁 하부 종단면을 찾습니다.','태반(Placenta), 자궁벽, 태반 하연(Leading edge), 내자궁구의 관계를 확인합니다. 제대 태반 부착부는 별도 추적으로 확인합니다.','방광 팽창과 국소 자궁수축이 위치를 왜곡할 수 있어 재확인합니다. 경복부로 하연–내구 관계가 불명확하면 적응증에 따라 경질초음파로 평가합니다.',['태반 위치와 형태를 기록하되 초기의 낮은 위치를 만삭까지 지속되는 전치태반으로 단정하지 않습니다.','하연과 내자궁구의 관계를 확인하고 낮거나 겹치면 적절한 후속 평가에 연결합니다.','이전 저위태반의 하연–내구 관계를 재평가합니다. 제대 혈관·하부 자궁 소견은 필요시 색 도플러와 표적 검사로 구분합니다.'],['mid','late']),
 cervix:P('경부 길이 평가가 필요한 경우 방광을 비운 상태에서 경질초음파(TVS)의 경부 정중시상면을 찾습니다.','탐촉자 압박을 최소화하면서 경관의 앞뒤 입술이 비슷한 두께가 되도록 정렬하고 경부가 화면의 50–75% 정도를 차지하게 확대합니다.','내자궁구(Internal os), 경관(Endocervical canal), 점막과 외자궁구(External os)가 이어져 보여야 합니다.','압박에 따른 인위적 연장과 하부 자궁을 경부로 오인하는 오류를 교정합니다. 시간에 따른 변화를 관찰하며 3회 이상 측정하고 기술적으로 적절한 최단 길이를 기록합니다.',['하부 자궁과 경부의 경계가 어려울 수 있습니다. 1분기 측정의 목적과 한계를 명시하고 중기의 선별 기준을 그대로 적용하지 않습니다.','내구–외구 사이의 정확한 경관을 기준으로 측정합니다. 방광 팽창·과한 압박·점액에 의한 가성 깔때기를 배제합니다.','후기 경부 변화를 중기 선별검사와 같은 의미로 해석하지 않습니다. 증상·적응증에 따라 측정하고 동적 단축·깔때기 변화와 관찰 조건을 기록합니다.'],['cervix']),
 profile:P('태아 전체가 보이는 정중시상면을 찾고 머리와 엉덩이를 한 화면에 놓습니다.','태아가 굽거나 과신전되지 않은 중립 자세에서 몸통 장축을 펼치고 머리·엉덩이 끝이 선명하도록 확대합니다.','머리끝(Crown), 엉덩이끝(Rump), 얼굴 프로파일과 몸통을 확인하고 팔다리를 CRL 끝점에서 제외합니다.','비스듬한 면이나 굽힌 자세에서 가장 긴 대각선을 재지 않습니다. 중립 자세의 올바른 정중면에서 두 끝점 사이를 직선 측정합니다.',['CRL(Crown–rump length)은 1분기 주수 평가용입니다. 적절한 확대와 중립 자세를 확보한 뒤 해당 주수의 표준에 따라 측정합니다.','중기 주수·성장 평가는 CRL 대신 해당 생체계측 항목을 사용합니다.','후기 성장 평가는 CRL 대신 HC·AC·FL 등의 기준을 따릅니다.'],['first']),
 nt:P('태아 머리·상흉부의 정중시상면에서 얼굴 윤곽을 확인합니다.','목을 중립 위치로 맞추고 머리와 상흉부를 크게 확대합니다. 피부와 양막(Amnion)을 구별하면서 목 뒤 액체 공간의 경계를 선명하게 조절합니다.','목덜미 투명대(Nuchal translucency)의 양쪽 밝은 경계와 가장 넓은 투명 공간을 확인합니다. 비골·구개·간뇌 등 정중면 표지를 함께 확인합니다.','가장 넓은 부위에서 경계 안쪽에 캘리퍼를 놓습니다. 양막을 피부로 잡거나 과신전·과굴곡 자세에서 측정하지 않습니다. 기술적으로 적절한 측정을 반복합니다.',['인증된 검사 프로토콜의 주수·CRL 범위와 캘리퍼 원칙을 따릅니다. NT는 중기의 목덜미 주름(NF)과 다른 측정입니다.','NT의 1분기 기준을 중기 NF에 대입하지 않습니다.','NT를 후기 목 뒤 두께 평가로 대체 적용하지 않습니다.'],['first'])
};
const earlyBrain={
 head:{start:'태아 머리의 축상면에서 두개골 윤곽과 대뇌낫(Falx)을 먼저 맞춥니다.',move:'맥락총이 보이는 높이에서 조금 아래로 스윕하여 양측 시상(Thalami)과 중뇌 구조가 보이는 초기 경시상면을 찾습니다.',landmarks:'두개골, 정중선, 양측 시상·측뇌실과 중뇌각(Cerebral peduncles)을 확인합니다. CSP는 초기 필수 표지로 요구하지 않습니다.',fix:'맥락총의 나비 모양을 시상으로 혼동하지 않습니다. BPD/HC를 측정한다면 초기 주수에 맞는 단면·참고치와 캘리퍼 원칙을 적용합니다.'},
 cerebellum:{start:'초기 머리 축상면에서 대뇌낫과 양측 시상을 확인하고 후두와 방향을 파악합니다.',move:'뒤쪽으로 조금씩 기울이고 위아래로 미세 스윕하여 초기 소뇌와 제4뇌실을 찾습니다. 후기처럼 큰 틸트나 고정 각도를 강제하지 않습니다.',landmarks:'시상, 초기 소뇌(Cerebellum), 제4뇌실(Fourth ventricle), 중뇌수도관과 후두와 액체 공간을 주수에 맞게 확인합니다.',fix:'정중시상면의 뇌간·두개내 투명대(IT)와 후두와 관계로 보완합니다. NT와 NF를 혼동하지 않고 완성된 충부의 모양을 필수 조건으로 요구하지 않습니다.'}
};
const cardiac=new Set(['heart','lvot','rvot','threev','threevpa','vessels','aoarch','ductarch','bicaval']);
function cycleStep(v){
 if(!v.temporal)return null;
 if(v.type==='heart')return v.id==='4ch-es'?'Cine를 앞뒤로 확인하여 심실강이 가장 작아지는 수축 말기를 고릅니다. 방실판은 닫혀 있고 심실 유입이 시작되기 전인지 확인합니다.':v.id==='4ch-ed'?'심실 충만이 끝나 심실강이 가장 큰 시점, 수축이 시작되기 직전을 cine로 찾습니다. 인접 프레임의 방실판 닫힘과 심실 수축 시작을 함께 확인합니다.':'방실판이 열리고 심실 충만이 시작되는 이완기 초기 프레임을 cine로 찾습니다. 가장 큰 심실 프레임을 이완기 초기로 혼동하지 않습니다.';
 return v.id.endsWith('-ed')?'Cine에서 심실 충만이 끝난 직후·수축 직전의 이완 말기를 찾습니다. 반월판이 닫힌 상태인지 인접 프레임으로 확인합니다. 유출 혈류가 가장 큰 수축기 프레임과 구분합니다.':'Cine에서 반월판이 열리고 심실에서 대혈관으로 박출되는 수축기 프레임을 찾습니다. 필요시 적절한 색 도플러로 전향성 유출을 확인하며 정지 모양만으로 주기를 판정하지 않습니다.';
}
export function acquisitionFor(v){
 const base=protocols[v.type];if(!base)return null;
 const trimester=v.trimester||2,p={...base,...(trimester===1?earlyBrain[v.type]:null)};
 if(trimester===1&&v.type==='genitalia')Object.assign(p,{start:'태아 하복부와 골반을 포함하는 정중시상면을 찾습니다.',move:'목·몸통이 과굴곡되지 않은 자세에서 골반 앞쪽 생식결절을 찾도록 좌우로 미세 스윕합니다.',landmarks:'생식결절(Genital tubercle)과 몸통의 기준 축을 확인합니다. 후기의 음순·음낭 표지를 적용하지 않습니다.'});
 const steps=[['기준 평면 획득',p.start],['이동·회전·틸트',p.move],['핵심 랜드마크 정렬',p.landmarks],['오류 교정·저장',p.fix],[`${trimester}분기 적용`,p.ages[trimester-1]]];
 const timing=cycleStep(v);if(timing)steps.push(['심장 주기 선택 · Cine',timing]);
 const keys=[['first','mid','late'][trimester-1],...p.refs];
 return {trimester,steps,refs:[...new Set(keys)].map(k=>acquisitionSources[k]),note:cardiac.has(v.type)&&trimester===1?'1분기 색·스펙트럴 도플러는 임상적 필요가 있을 때 최소 출력·최단 시간으로 사용합니다.':'방향은 화면 좌우가 아닌 태아의 머리·꼬리·등·배를 기준으로 합니다. 작은 조작 후 랜드마크를 다시 확인하세요.'};
}
export function renderAcquisition(v){const p=acquisitionFor(v);if(!p)return '';return `<section class="acquisition-guide" aria-label="분기별 단면 획득 프로토콜"><h3>단면 획득 프로토콜 <small>${p.trimester}분기 · Step-by-Step</small></h3><p class="acquisition-intro">가이드라인의 단면 기준을 바탕으로 정리한 교육용 획득 순서입니다. 실제 태위·주수에 따라 조절합니다.</p><ol>${p.steps.map(([title,text])=>`<li><strong>${title}</strong><p>${text}</p></li>`).join('')}</ol>${renderScanTips(v)}<p class="acquisition-note">${p.note}</p><div class="acquisition-sources">${p.refs.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener">${name} ↗</a>`).join('')}</div></section>`;}
